-- Whether an attendee's address came from their account, kept on the row
-- (generated by drizzle-kit, then completed by hand).
--
-- A schedule hid an attendee's address from its organizer when the attendee
-- had an account and the organizer held no contact address for them: the
-- address was the account's, never given by the organizer. That was read from
-- `user_id`, which deleting the account nulls, so the address was shown, and
-- searchable, from then on.
--
-- Every row with an account was hidden by that rule, and stays so. A Space
-- schedule's attendees are always its members, so theirs came from accounts
-- too, including any whose account is already gone. A personal schedule's
-- attendee whose account is already gone cannot be told apart from an address
-- the organizer typed, and is left shown, as it has been since.
ALTER TABLE `meeting_schedule_attendees` ADD `email_from_account` integer DEFAULT false NOT NULL;--> statement-breakpoint
UPDATE `meeting_schedule_attendees` SET `email_from_account` = true
WHERE `user_id` IS NOT NULL
  OR EXISTS (
    SELECT 1 FROM `meeting_schedules`
    INNER JOIN `spaces` ON `spaces`.`id` = `meeting_schedules`.`space_id`
    WHERE `meeting_schedules`.`id` = `meeting_schedule_attendees`.`schedule_id`
      AND `spaces`.`kind` = 'shared'
  );--> statement-breakpoint
PRAGMA optimize;
